/*
 * Program ID   : PR_DM_STRETCH_GOAL_81_DATA
 * Description  : 자동차사업부 STRETCH GOAL 데이터 입력
 * Program History
 *============================================================================================================
 *   Date       In Charge              Description
 *============================================================================================================
*  2023-01-03	CHANO0612		스크립트 추가


** -----------------------------------------------------------------------------------------------------------
*/

-- EXEC PR_DM_STRETCH_GOAL_81_DATA

CREATE PROCEDURE [dbo].[PR_DM_STRETCH_GOAL_81_DATA]
AS
BEGIN 
	SET NOCOUNT ON; 
	SET TRANSACTION ISOLATION LEVEL READ COMMITTED;
	SET XACT_ABORT ON;
	
	-- LOG 용 변수 설정
    DECLARE @v_program_name NVARCHAR(150) = 'PR_DM_STRETCH_GOAL_81_DATA';
	DECLARE @v_batch_user	NVARCHAR(150) = 'DM_STRETCH_GOAL';
    DECLARE @v_log_type     NVARCHAR(30); -- START/END/ERROR/...
    DECLARE @n_log_count    INTEGER = 0;
    DECLARE @v_log_message  NVARCHAR(1000);
    DECLARE @v_description  NVARCHAR(500);
    DECLARE @d_event_date   DATETIME;
	DECLARE	@v_OK_description		NVARCHAR(1200);	-- cut off Generated Number	
	
	-- 시작 LOG  (START)
	SET @v_log_type = 'START';
	SET @v_log_message = '########## Start of procedure ##########';
    SET @v_description = N'@p_division_id : 81, 자동차사업부 STRETCH GOAL 데이터 입력'
	SET @d_event_date = SYSDATETIME();
	EXEC PR_SCM_SYS_LOG_BATCH @v_program_name, @v_log_type, @n_log_count, @v_log_message, @v_description, @d_event_date;
	SET @v_log_message = NULL      /*-- <- 변수 재사용을 위하여 초기화해야함 --*/
	-- 시작 LOG  (END)

	DECLARE @SEQ				INT;

	BEGIN TRY

	DECLARE @V_RESTRICT_START_YYYYMMDD NCHAR(8)

	SELECT @V_RESTRICT_START_YYYYMMDD = ATTRIBUTE1 
	FROM SCM_ADM_LOOKUP_MASTER_DETAIL
	WHERE LOOKUP_TYPE = 'DM_STRETCH_GOAL_START_DATE'
		AND SEGMENT1 = '81'
		AND VALID_YN = 'Y'

	SET @V_RESTRICT_START_YYYYMMDD = '20230102'

	-- TEMP TABLE 확인후 삭제
	IF OBJECT_ID (N'tempdb..#STRETCH_GOAL_DATA', N'U') IS NOT NULL 
		DROP TABLE #STRETCH_GOAL_DATA

	CREATE TABLE #STRETCH_GOAL_DATA  (
			SEQ				  INT
			,DIVISION_ID      NVARCHAR(30) NOT NULL
			,PROJECT_CODE     NVARCHAR(50) NOT NULL
			,SCM_SITE_ID      NVARCHAR(30) NOT NULL
			,ITEM_ID          NVARCHAR(50) NOT NULL
			,DOM_EXP          NVARCHAR(03) NOT NULL
			,FCST_TYPE        NVARCHAR(20) NOT NULL
			,INCOTERMS        NVARCHAR(10) NOT NULL
			,PLANT_SITE_ID    NVARCHAR(30) NOT NULL
			,MEASURE          NVARCHAR(10) NULL
			,YYYYMMDD         NVARCHAR(10) NULL
			,QTY              NUMERIC(30,10) NOT NULL
	)



			-- EXEC PR_DM_STRETCH_GOAL_81_DATA

			-- SELECT * FROM #STRETCH_GOAL_DATA

			DELETE FROM DM_PLN_MKT_FCST WHERE YYYYMMDD >= '20230101' AND DIVISION_ID IN ('81', '81_UC')

			MERGE INTO [dbo].[DM_PLN_MKT_FCST] A
			USING ( SELECT  DIVISION_ID     
							,PROJECT_CODE 	
							,SCM_SITE_ID  	
							,ITEM_ID      	
							,DOM_EXP      	
							,FCST_TYPE    	
							,INCOTERMS    	
							,PLANT_SITE_ID	
							,MEASURE      	
							,YYYYMMDD     	
							,QTY          	
					 FROM   #STRETCH_GOAL_DATA WITH(NOLOCK)

				) B
				ON (    
					  A.DIVISION_ID			=  B.DIVISION_ID
					  AND A.PROJECT_CODE	=  B.PROJECT_CODE
					  AND A.SCM_SITE_ID		=  B.SCM_SITE_ID
					  AND A.ITEM_ID			=  B.ITEM_ID
					  AND A.DOM_EXP			=  B.DOM_EXP
					  AND A.FCST_TYPE		=  B.FCST_TYPE
					  AND A.INCOTERMS		=  B.INCOTERMS
					  AND A.PLANT_SITE_ID	=  B.PLANT_SITE_ID
					  AND A.MEASURE			=  B.MEASURE
					  AND A.YYYYMMDD		=  B.YYYYMMDD

				)
							  WHEN MATCHED THEN
				 UPDATE SET 
							 A.QTY		 = B.QTY		
							,A.LAST_UPDATED_BY			 =  @v_batch_user
							,A.LAST_UPDATE_DATE			 =  GETDATE()
					                
			  WHEN NOT MATCHED THEN
				 INSERT (  
							DIVISION_ID           
							,PROJECT_CODE 		
							,SCM_SITE_ID  		
							,ITEM_ID      			
							,DOM_EXP      			
							,FCST_TYPE    		
							,INCOTERMS    		
							,PLANT_SITE_ID			
							,MEASURE      			
							,YYYYMMDD     			
							,QTY          		
							,created_by
							,creation_date
							,last_updated_by
							,last_update_date
						)
				 VALUES (   
							 B.DIVISION_ID
							,B.PROJECT_CODE
							,B.SCM_SITE_ID
							,B.ITEM_ID
							,B.DOM_EXP
							,B.FCST_TYPE
							,B.INCOTERMS
							,B.PLANT_SITE_ID
							,B.MEASURE
							,B.YYYYMMDD
							,B.QTY
						   ,@v_batch_user   
						   ,GETDATE()
						   ,@v_batch_user
						   ,GETDATE()
						);

		SELECT YYYYMMDD, MEASURE, COUNT(*) AS MF_CURRENT_CNT, SUM(QTY) AS MF_CURRENT_AMT
		FROM DM_PLN_MKT_FCST (NOLOCK)
		WHERE DIVISION_ID IN ('81', '81_UC')
		AND YYYYMMDD >= @V_RESTRICT_START_YYYYMMDD
		AND QTY <> 0
		GROUP BY YYYYMMDD, MEASURE
		ORDER BY 1, 2

	END TRY
	BEGIN CATCH
	
		SET @v_log_type = 'ERROR';
		SET @v_log_message = CAST(ERROR_MESSAGE() AS NVARCHAR(1000));
		SET @v_description = 'ERROR_LINE : ' + STR(ERROR_LINE());
		SET @d_event_date = SYSDATETIME();

		SELECT '[' + Convert(NVARCHAR(10), ERROR_NUMBER()) + ']' + ERROR_MESSAGE();  /*-- 에러메시지 DISPLAY --*/
	  
		--[C20200909-000203] LOG 표준화 적용
		EXEC PR_SCM_SYS_LOG_BATCH @v_program_name, @v_log_type, @n_log_count, @v_log_message, @v_description, @d_event_date;

	END CATCH

	    -- 종료 LOG
    SET @v_log_type = 'END';
    SET @v_log_message = '########## END of procedure ##########';
    SET @v_description = N'@p_division_id : 81, 자동차사업부 STRETCH GOAL 데이터 입력'
    SET @d_event_date = SYSDATETIME();
    EXEC PR_SCM_SYS_LOG_BATCH @v_program_name, @v_log_type, @n_log_count, @v_log_message, @v_description, @d_event_date;


END




